        // Assuming standard Tabula TextChunk constructor signature
        TextChunk chunk1 = new TextChunk(10.0f, 20.0f, 50.0f, 10.0f);
        chunk1.setText("Hello");

        // 1. Test adding to an empty Line (Initializes bounds)
        line.addTextChunk(chunk1);

        List<TextChunk> elements = line.getTextElements();
        
        // Verify list update
        Assert.assertEquals("List size should be 1", 1, elements.size());
        Assert.assertEquals("First element should be chunk1", chunk1, elements.get(0));

        // Verify geometric bounds update (Intention: setRect)
        // The line should now have the exact dimensions of the first chunk
