        Assert.assertEquals("Line left should match chunk1", chunk1.getLeft(), line.getLeft(), 0.001f);
        Assert.assertEquals("Line width should match chunk1", chunk1.getWidth(), line.getWidth(), 0.001f);
        Assert.assertEquals("Line height should match chunk1", chunk1.getHeight(), line.getHeight(), 0.001f);

        // Create a second TextChunk positioned to the right of the first
        // Left at 80 (previous left 20 + width 50 + gap 10)
        TextChunk chunk2 = new TextChunk(10.0f, 80.0f, 30.0f, 10.0f);
        chunk2.setText("World");

        // 2. Test adding to a non-empty Line (Expands bounds)
        line.addTextChunk(chunk2);

        elements = line.getTextElements();

        // Verify list update
        Assert.assertEquals("List size should be 2", 2, elements.size());
        Assert.assertEquals("Second element should be chunk2", chunk2, elements.get(1));

        // Verify geometric bounds update (Intention: merge)
        // The line should expand to encompass both chunks
        // New width = (chunk2 Right Edge) - (chunk1 Left Edge) = (80 + 30) - 20 = 90
